{
  "name": "critical",
  "version": "9.0.0",
  "description": "Extract & inline critical-path CSS — two engines, automatic routing, agent-native.",
  "keywords": [
    "above-the-fold",
    "critical",
    "css",
    "inline",
    "lcp",
    "mcp",
    "performance"
  ],
  "license": "Apache-2.0",
  "author": "Addy Osmani",
  "repository": "addyosmani/critical",
  "bin": {
    "critical": "./cli.js"
  },
  "files": [
    "cli.js",
    "src"
  ],
  "type": "module",
  "types": "./src/index.d.ts",
  "exports": {
    ".": {
      "types": "./src/index.d.ts",
      "default": "./src/index.js"
    },
    "./mcp": {
      "types": "./src/mcp.d.ts",
      "default": "./src/mcp.js"
    }
  },
  "scripts": {
    "test": "node --test",
    "test:coverage": "node --test --experimental-test-coverage",
    "check": "vp check",
    "prepare": "vp config",
    "bench": "node bench/vs-beasties.mjs",
    "demo": "node cli.js ./fixtures --explain"
  },
  "dependencies": {
    "css-tree": "^3.1.0",
    "lightningcss": "^1.30.0",
    "linkedom": "^0.18.6"
  },
  "devDependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "@vitest/coverage-v8": "catalog:",
    "beasties": "^0.3.0",
    "playwright": "^1.50.0",
    "vite": "catalog:",
    "vite-plus": "catalog:",
    "vitest": "catalog:"
  },
  "peerDependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "playwright": "^1.50.0"
  },
  "peerDependenciesMeta": {
    "playwright": {
      "optional": true
    },
    "@modelcontextprotocol/sdk": {
      "optional": true
    }
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "packageManager": "pnpm@11.5.0"
}

{
  "name": "skills.addy.ie",
  "type": "module",
  "version": "1.0.0",
  "private": true,
  "description": "The developer site for agent-skills — production-grade engineering skills for AI coding agents.",
  "scripts": {
    "dev": "astro dev",
    "start": "astro dev",
    "build": "astro build",
    "preview": "astro preview",
    "astro": "astro"
  },
  "dependencies": {
    "@astrojs/sitemap": "^3.2.1",
    "astro": "^5.13.0"
  }
}

// @ts-check
import { defineConfig } from 'astro/config';
import sitemap from '@astrojs/sitemap';

// https://astro.build
export default defineConfig({
  site: 'https://skills.addy.ie',
  trailingSlash: 'always',
  integrations: [sitemap()],
  build: {
    inlineStylesheets: 'auto',
  },
  devToolbar: {
    enabled: false,
  },
});

import { defineConfig, globalIgnores } from "eslint/config";
import nextVitals from "eslint-config-next/core-web-vitals";
import nextTypescript from "eslint-config-next/typescript";

export default defineConfig([
  ...nextVitals,
  ...nextTypescript,
  globalIgnores([".next/**", "out/**", "coverage/**", "next-env.d.ts"]),
]);

{
  "extends": "next/core-web-vitals"
}

{
  "name": "agent-house",
  "version": "0.1.2",
  "description": "Lighthouse for agents - score an agent run trace, then tell it how to get faster and cheaper.",
  "keywords": [
    "agent",
    "llm",
    "observability",
    "opentelemetry",
    "otel",
    "genai",
    "profiler",
    "cost",
    "latency",
    "vercel-ai-sdk",
    "langgraph",
    "adk"
  ],
  "license": "MIT",
  "author": "Addy Osmani",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/addyosmani/agent-house.git"
  },
  "bugs": {
    "url": "https://github.com/addyosmani/agent-house/issues"
  },
  "homepage": "https://github.com/addyosmani/agent-house#readme",
  "type": "module",
  "sideEffects": false,
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "bin": {
    "agent-house": "./dist/cli.js"
  },
  "files": [
    "dist",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "test": "vitest run",
    "test:watch": "vitest",
    "test:coverage": "vitest run --coverage",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run typecheck && npm test && npm run build"
  },
  "devDependencies": {
    "@types/node": "^20.11.0",
    "typescript": "^5.4.0",
    "vitest": "^1.6.0"
  }
}

